<script setup>
import {computed,onMounted,reactive,ref,watch} from 'vue'
import axios from 'axios'
import {ElMessage} from 'element-plus'

defineEmits(['create-bug-for-task'])
const props=defineProps({page:{type:String,required:true},projectId:{type:[Number,String],default:null},projectName:{type:String,default:''},userName:{type:String,default:''},canManageQuality:{type:Boolean,default:false},releasePermissions:{type:Object,default:()=>({})},tasks:{type:Array,default:()=>[]},bugs:{type:Array,default:()=>[]},requirements:{type:Array,default:()=>[]}})
const api=axios.create({baseURL:'/api'});api.interceptors.request.use(c=>{const t=localStorage.getItem('hetu_token');if(t)c.headers.Authorization=`Bearer ${t}`;return c})
const toast=(message,type='success')=>ElMessage({message,type,duration:2400})
const localDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
const today=localDate(),monthStart=`${today.slice(0,7)}-01`
const from=ref(monthStart),to=ref(today),logs=ref([]),ranking=ref([]),deductions=ref([]),releases=ref([]),loading=ref(false)
const progressForm=reactive({taskId:'',progress:0,workDate:today,note:''})
const workHours=ref({}),workDate=ref(today)
const releaseForm=reactive({name:'v1.0',releaseDate:today,description:''})
const deductionForm=reactive({person:'',category:'生产问题',hours:1,occurredOn:today,note:''})
const requirementToAdd=ref(''),bugToAdd=ref('')
const releaseDialog=reactive({open:false,id:null,mode:'',date:'',note:'',passed:true,name:''})
const pageTitles={taskPool:'任务池',worklog:'工时与排名',testing:'正在测试',releases:'发布计划',quality:'质量负面清单'}
const poolTasks=computed(()=>props.tasks.filter(t=>!t.assignee&&t.status==='TODO'&&(!props.projectId||String(t.projectId)===String(props.projectId))))
const testTasks=computed(()=>props.tasks.filter(t=>t.status==='TESTING'&&(!props.projectId||String(t.projectId)===String(props.projectId))))
const myTasks=computed(()=>props.tasks.filter(t=>t.assignee===props.userName&&t.status==='IN_PROGRESS'&&(!props.projectId||String(t.projectId)===String(props.projectId))))
const projectRequirements=computed(()=>props.requirements.filter(r=>!props.projectId||String(r.projectId)===String(props.projectId)))
const projectBugs=computed(()=>props.bugs.filter(b=>{const t=props.tasks.find(x=>String(x.id)===String(b.taskId));return !props.projectId||String(t?.projectId)===String(props.projectId)}))
const fmtHours=value=>`${Number(value||0).toFixed(2).replace(/\.00$/,'')} h`
async function refresh(){loading.value=true;try{if(props.page==='worklog'){const{data}=await api.get('/hetu/worklog',{params:{from:from.value,to:to.value,projectId:props.projectId}});logs.value=data.data?.entries||[];ranking.value=data.data?.ranking||[]}if(props.page==='quality'){const{data}=await api.get('/hetu/deductions',{params:{from:from.value,to:to.value,projectId:props.projectId}});deductions.value=data.data||[]}if(props.page==='releases'){const{data}=await api.get('/hetu/releases',{params:{projectId:props.projectId}});releases.value=data.data||[]}}catch(e){toast(e.response?.data?.msg||'数据加载失败','error')}finally{loading.value=false}}
watch(()=>[props.page,props.projectId],refresh,{immediate:true})
async function submitProgress(){if(!progressForm.taskId){toast('请选择任务','warning');return}try{await api.patch(`/hetu/tasks/${progressForm.taskId}/progress`,{progress:Number(progressForm.progress),workDate:progressForm.workDate,note:progressForm.note||'每日进度'});toast('进度已更新');progressForm.note='';await refresh();window.dispatchEvent(new CustomEvent('hetu-refresh'))}catch(e){toast(e.response?.data?.msg||'进度提交失败','error')}}
async function submitWorkHours(task){const hours=Number(workHours.value[task.id]);if(!hours||hours<=0){toast('填写本次新增工时','warning');return}try{await api.post('/hetu/worklog',{taskId:task.id,hours,workDate:workDate.value,note:''});workHours.value[task.id]='';toast(`已登记 ${hours} 小时`);await refresh()}catch(e){toast(e.response?.data?.msg||'工时登记失败','error')}}
async function claim(task){try{await api.post(`/hetu/tasks/${task.id}/claim`);toast('任务已领取');window.dispatchEvent(new CustomEvent('hetu-refresh'))}catch(e){toast(e.response?.data?.msg||'领取失败','error')}}
async function testResult(task,status){try{await api.patch(`/hetu/tasks/${task.id}/status`,{status,note:status==='DONE'?'测试通过':'测试未通过，退回开发'});toast(status==='DONE'?'测试通过':'已退回开发');window.dispatchEvent(new CustomEvent('hetu-refresh'))}catch(e){toast(e.response?.data?.msg||'测试状态更新失败','error')}}
async function createRelease(){if(!releaseForm.name.trim()){toast('请填写版本名称','warning');return}try{await api.post('/hetu/releases',{...releaseForm,projectId:props.projectId,status:'PLANNED'});toast('发布计划已创建');await refresh()}catch(e){toast(e.response?.data?.msg||'创建发布计划失败','error')}}
const releaseStatusLabel=status=>({PLANNED:'计划中',READY:'测试通过，待发布',RELEASED:'已发布，待产品验证',NEEDS_IMPROVEMENT:'已验证待完善',VERIFIED:'已验证通过',CLOSED:'已关闭'}[status]||status)
async function releaseAction(release,action,payload={}){if(action==='schedule'||action==='verify'){releaseDialog.open=true;releaseDialog.id=release.id;releaseDialog.mode=action;releaseDialog.date=release.releaseDate?.slice(0,10)||today;releaseDialog.passed=payload.passed!==false;releaseDialog.note=action==='verify'?(payload.passed?'验证通过':'线上缺陷待修复'):'';releaseDialog.name=release.name;return}try{if(action==='close')await api.post(`/hetu/releases/${release.id}/close`,{note:'人工确认关闭'});else await api.post(`/hetu/releases/${release.id}/${action}`);toast('发布计划状态已更新');await refresh()}catch(e){toast(e.response?.data?.msg||'发布计划操作失败','error')}}
async function submitReleaseDialog(){try{if(releaseDialog.mode==='schedule'){if(!releaseDialog.date){toast('请选择发布日期','warning');return}await api.patch(`/hetu/releases/${releaseDialog.id}/schedule`,{releaseDate:releaseDialog.date})}else{await api.post(`/hetu/releases/${releaseDialog.id}/verify`,{status:releaseDialog.passed?'VERIFIED':'NEEDS_IMPROVEMENT',note:releaseDialog.note})}releaseDialog.open=false;toast('发布计划状态已更新');await refresh()}catch(e){toast(e.response?.data?.msg||'发布计划操作失败','error')}}
async function addItem(release,entityType,entityId){if(!entityId)return;try{await api.post(`/hetu/releases/${release.id}/items`,{entityType,entityId:Number(entityId)});toast('已加入发布计划');requirementToAdd.value='';bugToAdd.value='';await refresh()}catch(e){toast(e.response?.data?.msg||'加入失败','error')}}
async function addDeduction(){if(!deductionForm.person.trim()||!deductionForm.category.trim()){toast('请填写责任人和事项类型','warning');return}try{await api.post('/hetu/deductions',{...deductionForm,projectId:props.projectId});toast('已记录到负面清单');deductionForm.note='';await refresh()}catch(e){toast(e.response?.data?.msg||'记录失败','error')}}
</script>

<template>
  <section class="core-workspace">
    <header class="core-head"><div><div class="core-kicker">{{projectName}}</div><h1>{{pageTitles[page]}}</h1><p>{{page==='worklog'?'在自己的进行中任务旁登记新增工时；统计与提交分开展示。':page==='taskPool'?'无人负责的任务可以由工程师自行领取。':page==='testing'?'所有开发进度达到 100% 的任务会自动进入正在测试列表。':page==='releases'?'把确认后的需求和待发布修复汇总到一个版本计划。':'记录缺陷扣分和日常质量事项，形成可追溯的个人清单。'}}</p></div></header>
    <template v-if="page==='taskPool'"><div class="core-list"><article v-for="t in poolTasks" :key="t.id" class="core-row"><div><b>{{t.title}}</b><small>{{t.priority==='HIGH'?'高优先级':'常规'}} · 预估 {{fmtHours(t.estimateHours)}} · {{t.dueDate||'未设截止日期'}}</small></div><button class="core-button" @click="claim(t)">领取任务</button></article><p v-if="!poolTasks.length" class="core-empty">当前项目没有待领取任务。</p></div></template>
    <template v-else-if="page==='worklog'"><div class="core-card"><div class="core-card-head"><div><h2>我的进行中任务</h2><p>填写本次新增工时，点击“登记”即可记入工时统计。</p></div><label class="inline-date">日期<input v-model="workDate" type="date"/></label></div><div class="table-scroll"><table class="work-table"><thead><tr><th>工作项</th><th>状态</th><th>预估工时</th><th>进度</th><th>本次新增工时</th><th></th></tr></thead><tbody><tr v-for="t in myTasks" :key="t.id"><td><b>{{t.title}}</b><small>{{projectName}} · #TASK-{{t.id}}</small></td><td><span class="work-status">进行中</span></td><td>{{fmtHours(t.estimateHours)}}</td><td>{{t.progress||0}}%</td><td><input v-model="workHours[t.id]" class="hours-input" type="number" min="0.25" max="24" step="0.25" placeholder="小时"/></td><td><button class="core-button" @click="submitWorkHours(t)">登记</button></td></tr><tr v-if="!myTasks.length"><td colspan="6" class="core-empty">当前没有进行中的个人任务。</td></tr></tbody></table></div></div><div class="core-card"><div class="core-card-head"><h2>工时统计与排名</h2><div class="date-range"><input v-model="from" type="date"/><span>至</span><input v-model="to" type="date"/><button class="core-button secondary" @click="refresh">查询</button></div></div><div class="table-scroll"><table class="work-table"><thead><tr><th>排名</th><th>成员</th><th>累计工时</th><th>提交次数</th></tr></thead><tbody><tr v-for="(r,i) in ranking" :key="r.actor"><td>{{i+1}}</td><td><b>{{r.actor}}</b></td><td>{{fmtHours(r.hours)}}</td><td>{{r.submissions}}</td></tr><tr v-if="!ranking.length"><td colspan="4" class="core-empty">所选时间段暂无工时记录。</td></tr></tbody></table></div><h3 class="core-subhead">工时明细</h3><div class="table-scroll"><table class="work-table"><thead><tr><th>工作项</th><th>成员</th><th>日期</th><th>本次工时</th><th>记录</th></tr></thead><tbody><tr v-for="l in logs" :key="l.id"><td>{{l.taskTitle}}</td><td>{{l.actor}}</td><td>{{l.workDate}}</td><td>{{fmtHours(l.hours)}}</td><td>{{l.note||'—'}}</td></tr><tr v-if="!logs.length"><td colspan="5" class="core-empty">暂无工时记录。</td></tr></tbody></table></div></div></template>
    <template v-else-if="page==='testing'"><div class="core-card"><div class="core-card-head"><div><h2>正在测试的工作</h2><p>开发进度达到 100% 后自动进入此列表，需求与任务关系会自动带入缺陷。</p></div></div><div class="table-scroll"><table class="work-table"><thead><tr><th>任务</th><th>关联需求</th><th>开发负责人</th><th>进度</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="t in testTasks" :key="t.id"><td><b>{{t.title}}</b><small>#TASK-{{t.id}}</small></td><td>{{projectRequirements.find(r=>String(r.id)===String(t.requirementId))?.title||'—'}}</td><td>{{t.assignee||'未分配'}}</td><td>{{t.progress}}%</td><td><span class="work-status">正在测试</span></td><td><div class="core-actions"><button class="core-button secondary" @click="$emit('create-bug-for-task',t)">提 Bug</button><button class="core-button" @click="testResult(t,'DONE')">测试通过</button><button class="core-button secondary" @click="testResult(t,'IN_PROGRESS')">退回开发</button></div></td></tr><tr v-if="!testTasks.length"><td colspan="6" class="core-empty">当前没有正在测试的工作。</td></tr></tbody></table></div></div></template>
    <template v-else-if="page==='releases'"><div v-if="releasePermissions.add" class="core-card"><h2>新建发布计划</h2><div class="core-form release-form"><label>版本名称<input v-model="releaseForm.name" placeholder="例如 v1.1"/></label><label>计划发布日期<input v-model="releaseForm.releaseDate" type="date"/></label><label>发布说明<input v-model="releaseForm.description" placeholder="本次版本范围"/></label><button class="core-button" @click="createRelease">创建版本</button></div></div><div class="release-grid"><article v-for="r in releases" :key="r.id" class="core-card release-card"><div class="core-card-head"><div><h2>{{r.name}}</h2><p>{{r.releaseDate||'发布日期待定'}} · {{releaseStatusLabel(r.status)}}</p></div><span class="release-count">{{r.items?.length||0}} 项</span></div><p v-if="r.description" class="release-description">{{r.description}}</p><p v-if="r.verificationNote" class="release-description">验证记录：{{r.verificationNote}} · {{r.verifiedBy||''}}</p><div class="core-actions release-actions"><button v-if="releasePermissions.schedule&&(r.status==='PLANNED'||r.status==='READY')" class="core-button secondary" @click="releaseAction(r,'schedule')">调整日期</button><button v-if="releasePermissions.test&&r.status==='PLANNED'" class="core-button" @click="releaseAction(r,'submit-test')">测试通过并提交发布</button><button v-if="releasePermissions.publish&&r.status==='READY'" class="core-button" @click="releaseAction(r,'publish')">确认发布</button><button v-if="releasePermissions.verify&&r.status==='RELEASED'" class="core-button" @click="releaseAction(r,'verify',{passed:true})">验证通过</button><button v-if="releasePermissions.verify&&r.status==='RELEASED'" class="core-button secondary" @click="releaseAction(r,'verify',{passed:false})">验证待完善</button><button v-if="releasePermissions.close&&(r.status==='NEEDS_IMPROVEMENT'||r.status==='VERIFIED')" class="core-button secondary" @click="releaseAction(r,'close')">手动关闭</button></div><div v-for="item in r.items" :key="item.id" class="release-item"><span>{{item.entityType==='requirement'?'需求':'缺陷'}}</span><b>{{item.title||'内容已删除'}}</b><small>{{item.status}}</small></div><div v-if="releasePermissions.edit&&(r.status==='PLANNED'||r.status==='READY')" class="core-form add-release-items"><select v-model="requirementToAdd"><option value="">选择确认需求</option><option v-for="x in projectRequirements.filter(x=>x.status==='APPROVED')" :key="x.id" :value="x.id">{{x.title}}</option></select><button class="core-button secondary" @click="addItem(r,'requirement',requirementToAdd)">加入需求</button><select v-model="bugToAdd"><option value="">选择缺陷修复</option><option v-for="x in projectBugs.filter(x=>x.status==='CLOSED')" :key="x.id" :value="x.id">{{x.title}}</option></select><button class="core-button secondary" @click="addItem(r,'bug',bugToAdd)">加入缺陷</button></div></article><p v-if="!releases.length" class="core-empty">还没有发布计划。</p></div></template>
    <template v-else><div v-if="canManageQuality" class="core-card"><h2>记录日常质量事项</h2><div class="core-form quality-form"><label>责任人<input v-model="deductionForm.person" placeholder="填写成员姓名"/></label><label>事项类型<input v-model="deductionForm.category" placeholder="如未按时开周会、生产事故"/></label><label>扣减工时<input v-model.number="deductionForm.hours" type="number" min="0.01" max="1000" step="0.25"/></label><label>发生日期<input v-model="deductionForm.occurredOn" type="date"/></label><label>说明<input v-model="deductionForm.note" placeholder="原因或处理记录"/></label><button class="core-button" @click="addDeduction">记录事项</button></div></div><div class="core-card"><div class="core-card-head"><h2>个人负面清单</h2><div class="date-range"><input v-model="from" type="date"/><span>至</span><input v-model="to" type="date"/><button class="core-button secondary" @click="refresh">查询</button></div></div><div class="core-list"><article v-for="d in deductions" :key="d.id" class="core-row"><div><b>{{d.person}} · {{d.category}}</b><small>{{d.occurredOn}} · {{d.sourceType==='BUG'?'缺陷关闭扣分':'日常事项'}} <template v-if="d.note">· {{d.note}}</template></small></div><strong class="deduction-hours">{{fmtHours(d.hours)}}</strong></article><p v-if="!deductions.length" class="core-empty">所选时间段暂无负面记录。</p></div></div></template>
    <div v-if="page==='releases'&&releaseDialog.open" class="release-dialog-backdrop" @click.self="releaseDialog.open=false"><div class="release-dialog" role="dialog" aria-modal="true"><h2>{{releaseDialog.mode==='schedule'?'调整计划发布日期':releaseDialog.passed?'产品验证':'验证待完善'}}</h2><p>{{releaseDialog.name}}</p><label v-if="releaseDialog.mode==='schedule'">计划发布日期<input v-model="releaseDialog.date" type="date"/></label><label v-else>验证说明<textarea v-model="releaseDialog.note" rows="4" :placeholder="releaseDialog.passed?'填写验证结论':'填写需要完善的问题'"/></label><div class="core-actions"><button class="core-button secondary" @click="releaseDialog.open=false">取消</button><button class="core-button" @click="submitReleaseDialog">确认</button></div></div></div>
  </section>
</template>

<style scoped>
.core-workspace{max-width:1180px;margin:0 auto;padding:28px 32px 48px;color:#26334a}.core-head{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:20px}.core-kicker{font-size:11px;color:#8995aa;letter-spacing:.04em}.core-head h1{font-size:24px;margin:8px 0;color:#273650}.core-head p,.release-card p{font-size:13px;color:#8995a8;margin:0}.core-card,.core-list{background:white;border:1px solid #e9edf4;border-radius:12px;padding:18px 20px;margin-bottom:14px}.core-card h2{font-size:15px;margin:0 0 16px}.core-form{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));align-items:end;gap:12px}.core-form label{display:flex;flex-direction:column;gap:6px;font-size:12px;color:#6d7b91}.core-form input,.core-form select,.date-range input,.add-release-items select{height:36px;border:1px solid #dfe5ee;border-radius:7px;padding:0 9px;color:#36445b;background:#fff;min-width:0}.core-button{height:35px;border:1px solid #586ef1;border-radius:7px;background:#586ef1;color:white;padding:0 13px;cursor:pointer;white-space:nowrap}.core-button.secondary{background:white;color:#596fe7;border-color:#dce2f2}.core-row{display:flex;align-items:center;gap:14px;min-height:61px;border-bottom:1px solid #eef1f5}.core-row:last-child{border-bottom:0}.core-row>div:first-child{display:flex;flex-direction:column;gap:6px;flex:1;min-width:0}.core-row b{font-size:13px;color:#394861}.core-row small{font-size:11px;color:#909caf}.core-row>span:last-child{color:#5d6f8c;font-size:12px}.core-empty{padding:25px 10px;text-align:center;color:#98a3b3;font-size:13px}.core-actions{display:flex;gap:8px}.rank-row{display:grid;grid-template-columns:34px 1fr auto auto}.rank-no{color:#5c70e8!important}.core-card-head{display:flex;justify-content:space-between;align-items:center;gap:15px}.core-card-head h2{margin-bottom:0}.date-range{display:flex;align-items:center;gap:8px;font-size:12px;color:#7e8aa0}.date-range input{width:142px}.core-subhead{font-size:13px;margin:18px 0 4px;color:#69778c}.release-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.release-card{margin:0}.release-card h2{margin:0 0 5px}.release-count{border-radius:20px;padding:5px 10px;background:#eef1ff;color:#596fe7;font-size:11px}.release-description{margin:12px 0!important}.release-item{display:grid;grid-template-columns:52px 1fr auto;align-items:center;gap:9px;padding:9px 0;border-top:1px solid #eef1f5}.release-item span,.release-item small{font-size:10px;color:#8794a8}.release-item b{font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.add-release-items{grid-template-columns:minmax(90px,1fr) auto; margin-top:13px}.quality-form{grid-template-columns:repeat(3,minmax(0,1fr))}.deduction-hours{color:#dd6673!important}.release-form{grid-template-columns:1fr 1fr 1.4fr auto}
.release-dialog-backdrop{position:fixed;inset:0;background:#17233a88;display:grid;place-items:center;z-index:2000;padding:20px}.release-dialog{width:min(460px,100%);background:#fff;border-radius:12px;padding:24px;box-shadow:0 20px 70px #17233a44}.release-dialog h2{margin:0 0 8px;color:#273650;font-size:18px}.release-dialog p{margin:0 0 18px;color:#8794a8;font-size:13px}.release-dialog label{display:flex;flex-direction:column;gap:7px;color:#65738a;font-size:12px;margin-bottom:18px}.release-dialog input,.release-dialog textarea{width:100%;box-sizing:border-box;border:1px solid #dfe5ee;border-radius:7px;padding:10px;color:#36445b;font:inherit}.release-dialog input{height:38px}.release-dialog .core-actions{justify-content:flex-end}
.table-scroll{width:100%;overflow:auto}.work-table{width:100%;min-width:760px;border-collapse:separate;border-spacing:0;text-align:left;font-size:12px}.work-table th{padding:11px 13px;background:#f8f9fc;color:#8591a4;font-size:11px;font-weight:600;white-space:nowrap;border-bottom:1px solid #edf0f5}.work-table th:first-child{border-radius:8px 0 0 0}.work-table th:last-child{border-radius:0 8px 0 0}.work-table td{padding:12px 13px;border-bottom:1px solid #eef1f5;color:#526078;vertical-align:middle}.work-table tbody tr:last-child td{border-bottom:0}.work-table td:first-child b{display:block;color:#34425b;font-size:12px}.work-table td:first-child small{display:block;margin-top:4px;color:#98a3b3;font-size:10px}.work-status{display:inline-flex;padding:4px 8px;border-radius:14px;background:#eef1ff;color:#5c6de5;font-size:10px;white-space:nowrap}.hours-input{width:82px;height:33px;border:1px solid #dfe5ee;border-radius:7px;padding:0 9px;color:#36445b}.inline-date{display:flex;align-items:center;gap:8px;color:#7e8aa0;font-size:11px}.inline-date input{height:34px;border:1px solid #dfe5ee;border-radius:7px;padding:0 8px;color:#36445b}
@media(max-width:850px){.core-workspace{padding:20px 15px}.core-form,.quality-form,.release-form{grid-template-columns:repeat(2,minmax(0,1fr))}.release-grid{grid-template-columns:1fr}.core-card-head{align-items:flex-start;flex-direction:column}.date-range input{width:120px}}
</style>
